<style>
  .user-wizard{max-width:1080px;margin:0 auto;border:0!important;border-radius:16px!important;box-shadow:0 12px 34px rgba(16,24,40,.08);overflow:hidden}.user-wizard>.panel-heading{background:linear-gradient(110deg,#132238,#29466e)!important;color:#fff!important;border:0!important;padding:23px 28px!important;font:800 20px 'Manrope',sans-serif}.user-wizard .panel-body{padding:0!important;background:#fff}.wizard-steps{display:flex;padding:20px 28px;background:#f8faff;border-bottom:1px solid #e7edf6;gap:4px}.wizard-step{flex:1;position:relative;color:#8a97a8;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;cursor:pointer}.wizard-step:before{content:attr(data-step);display:flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:50%;background:#e5eaf2;color:#69778b;margin-bottom:7px}.wizard-step:not(:last-child):after{content:'';height:2px;background:#e5eaf2;position:absolute;top:13px;left:34px;right:5px}.wizard-step.active,.wizard-step.done{color:#305bd6}.wizard-step.active:before,.wizard-step.done:before{background:#4169e1;color:#fff;box-shadow:0 0 0 4px #e2e9ff}.wizard-step.done:after{background:#4169e1}.wizard-pane{display:none;padding:25px 28px 10px;min-height:350px}.wizard-pane.active{display:block;animation:wizardIn .3s ease}.wizard-pane h3{font:800 18px 'Manrope',sans-serif;margin:0 0 5px;color:#16243b}.wizard-pane .wizard-note{color:#7b8798;margin:0 0 22px;font-size:13px}.wizard-pane .form-group{margin-bottom:18px}.wizard-pane label{font-size:12px;color:#46556b}.wizard-pane .form-control{height:42px;border:1px solid #dbe3ee;border-radius:7px;box-shadow:none}.wizard-pane textarea.form-control{height:auto}.wizard-actions{display:flex;justify-content:space-between;align-items:center;padding:18px 28px;border-top:1px solid #edf1f6;background:#fbfcff}.wizard-actions .btn{border-radius:7px;padding:10px 17px;font-weight:700}.wizard-next,.wizard-submit{background:#4169e1!important;border-color:#4169e1!important}.wizard-submit{display:none}.wizard-progress{color:#748196;font-size:12px}@keyframes wizardIn{from{opacity:0;transform:translateX(12px)}to{opacity:1;transform:none}}@media(max-width:767px){.user-wizard>.panel-heading{padding:18px}.wizard-steps{padding:15px 12px;overflow-x:auto}.wizard-step{min-width:72px;font-size:9px}.wizard-pane{padding:20px 16px 8px}.wizard-actions{padding:15px 16px}.wizard-step:not(:last-child):after{right:0}}
</style>
